insert into public.content_copy (id, kind, key, title, body, workflow_status, is_fixture) values ('fixture_copy_disclaimer_onboarding', 'disclaimer', 'onboarding.wellness_disclaimer', 'Wellness tool disclaimer', '[FIXTURE] ThriveLife is a wellness and self-reflection tool. It does not provide diagnosis, treatment, or emergency support. Batteries rise and fall. Low is not failure — it is a signal to take a pit stop.', 'published', true) on conflict (id) do nothing;
