insert into public.content_copy (id, kind, key, title, body, workflow_status, is_fixture) values ('fixture_copy_notify_checkin', 'notification', 'notify.daily_checkin', 'Optional check-in reminder', '[FIXTURE] When you want a nudge: a short check-in can help you notice and match a recharge. You can turn reminders off anytime.', 'published', true) on conflict (id) do nothing;
